begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,auth;
select no_plan();
\ir fixtures/final-result-readiness-setup.sql
select ok(not has_function_privilege('anon','api.qry_final_result_publication_head_v2()','execute'),'anonymous caller cannot inspect manager recovery state');
select ok(not has_function_privilege('service_role','api.qry_final_result_release_approval_v2(uuid,uuid)','execute'),'service attestor cannot inspect actor approval through recovery API');
set local role authenticated;
select is(api.qry_final_result_publication_head_v2()->'data','null'::jsonb,'no current publication is an explicit null');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>'{data,activeApproval}','null'::jsonb,'prepared selection has no approval');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>'{data,publication}','null'::jsonb,'prepared selection has no publication');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000099')->'data','null'::jsonb,'absent exact run does not select another run');
select throws_ok($q$select api.qry_final_result_release_v2(null)$q$,'22023','Exact final Result run identity is required','run recovery needs identity');
select throws_ok($q$select api.qry_final_result_release_approval_v2(null,null)$q$,'22023','Exact final Result run and approval identities are required','approval recovery needs both identities');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000002',true);
select is(api.qry_final_result_publication_head_v2()->>'code','not_data_product_manager','ordinary user cannot inspect current recovery context');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000010','87960000-0000-4000-8000-000000000001')->>'code','not_data_product_manager','ordinary user cannot enumerate approval absence');
select set_config('request.jwt.claim.sub','87930000-0000-4000-8000-000000000001',true);
reset role;
set local role service_role;
select api.svc_final_result_readiness_begin_v2(pg_temp.readiness_header());
select api.svc_final_result_readiness_artifacts_v2('87950000-0000-4000-8000-000000000001',pg_temp.readiness_proofs());
select api.svc_final_result_readiness_seal_v2('87950000-0000-4000-8000-000000000001');
reset role;
create temporary table recovery_fixture(expiry timestamptz,approval jsonb,publication jsonb);
insert into recovery_fixture(expiry) values(clock_timestamp()+interval '1 hour');
grant select,update on recovery_fixture to authenticated;
set local role authenticated;
update recovery_fixture set approval=api.cmd_final_result_release_approve_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87950000-0000-4000-8000-000000000001','87960000-0000-4000-8000-000000000001',null,expiry,'synthetic recovery');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,activeApproval,approvalHash}',(select approval#>>'{data,approvalHash}' from recovery_fixture),'run returns exact active approval hash for confirmation');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000010','87960000-0000-4000-8000-000000000001')#>>'{data,status}','approved','exact read recovers approval after a lost ACK');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000010','87960000-0000-4000-8000-000000000001')#>>'{data,context,verificationId}','87950000-0000-4000-8000-000000000001','approval recovery retains original verification identity');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000099','87960000-0000-4000-8000-000000000001')->'data','null'::jsonb,'another run cannot claim a known approval');
update recovery_fixture set approval=api.cmd_final_result_release_approve_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87950000-0000-4000-8000-000000000001','87960000-0000-4000-8000-000000000002','87960000-0000-4000-8000-000000000001',expiry,'synthetic replacement');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000010','87960000-0000-4000-8000-000000000001')#>>'{data,status}','revoked','historical approval remains readable without revival');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,activeApproval,approvalId}','87960000-0000-4000-8000-000000000002','run shows replacement rather than historical approval');
update recovery_fixture set publication=api.cmd_final_result_release_activate_v2('87930000-0000-4000-8000-000000000010',pg_temp.final_plan_hash(),'87960000-0000-4000-8000-000000000002',approval#>>'{data,approvalHash}','87950000-0000-4000-8000-000000000001','synthetic-recovery',repeat('f',64));
select is(api.qry_final_result_publication_head_v2()#>>'{data,publicationId}',(select publication#>>'{data,publicationId}' from recovery_fixture),'current lookup matches committed publication');
select is(api.qry_final_result_publication_head_v2()#>>'{data,format}','final-result-pair.v2','current format is explicit');
select is(api.qry_final_result_publication_head_v2()#>>'{data,targetHash}',repeat('d',64),'current target is explicit');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>'{data,activeApproval}','null'::jsonb,'consumed approval is not active');
select is(api.qry_final_result_release_approval_v2('87930000-0000-4000-8000-000000000010','87960000-0000-4000-8000-000000000002')#>>'{data,status}','consumed','exact approval recovery shows consumption');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,publication,idempotencyKey}','synthetic-recovery','lost activation ACK can recover exact execution identity without writing');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,publication,verificationId}','87950000-0000-4000-8000-000000000001','recovery retains activation readiness binding');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,publicationAuthorized}','false','recovery read is not an authority grant');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>'{data,readbackReceipt}','null'::jsonb,'recovery does not invent post-publication observation');
select api.cmd_lca_release_unpublish((select (publication#>>'{data,publicationId}')::uuid from recovery_fixture),'synthetic recovery withdrawal');
select is(api.qry_final_result_publication_head_v2()->'data','null'::jsonb,'withdrawn publication no longer current');
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')#>>'{data,publication,isCurrent}','false','historical run recovery does not make publication current');
reset role;
delete from private.roles where user_id='87930000-0000-4000-8000-000000000001';
set local role authenticated;
select is(api.qry_final_result_release_v2('87930000-0000-4000-8000-000000000010')->>'code','not_data_product_manager','revoked manager loses cached recovery path');
reset role;
select is((select count(*) from private.lca_release_publications),1::bigint,'all recovery reads are side-effect free');
select * from finish();
rollback;
